{"path":"dist\shots\cdp.mjs","content":"// Scratch verification tool (not committed): drives headless Chrome over CDP.
// usage: node cdp.mjs <outDir> <name:path:width[:dark]> ...
import { spawn } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const [outDir, ...specs] = process.argv.slice(2);
mkdirSync(outDir, { recursive: true });
const port = 9333;
const proc = spawn(CHROME, ['--headless=new', '--disable-gpu', '--hide-scrollbars', `--remote-debugging-port=${port}`, '--user-data-dir=' + join(outDir, '.prof'), 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); if (targets.length) break; } catch {}
  await sleep(200);
}
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map();
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })).result?.result?.value;

const PROBE = `(() => {
  const vw = document.documentElement.clientWidth;
  const out = [];
  for (const el of document.querySelectorAll('body *')) {
    const r = el.getBoundingClientRect();
    if (r.width === 0) continue;
    if (r.right > vw + 1 || r.left < -1) {
      const cs = getComputedStyle(el);
      if (cs.position === 'fixed') continue;
      let p = el.parentElement, clipped = false;
      while (p && p !== document.body) { const o = getComputedStyle(p).overflowX; if (o === 'hidden' || o === 'auto' || o === 'scroll' || o === 'clip') { clipped = true; break; } p = p.parentElement; }
      if (clipped) continue;
      out.push((el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\\s+/).join('.') : '')) + ' L' + Math.round(r.left) + ' R' + Math.round(r.right));
    }
  }
  const small = [];
  for (const a of document.querySelectorAll('a,button')) {
    const r = a.getBoundingClientRect();
    if (r.width && (r.height < 24 || r.width < 24) && getComputedStyle(a).display !== 'inline') small.push(a.textContent.trim().slice(0, 20) + ' ' + Math.round(r.width) + 'x' + Math.round(r.height));
  }
  return { vw, scrollW: document.documentElement.scrollWidth, docH: document.documentElement.scrollHeight, overflow: out.slice(0, 25), smallTargets: small.slice(0, 15) };
})()`;

for (const spec of specs) {
  const [name, path, w, dark] = spec.split(':');
  const width = Number(w);
  await send('Emulation.setDeviceMetricsOverride', { width, height: 800, deviceScaleFactor: 1, mobile: width < 700 });
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: dark ? 'dark' : 'light' }] });
  await send('Page.enable');
  await send('Page.navigate', { url: 'http://127.0.0.1:4329' + path });
  await sleep(1800);
  const info = await evalJs(PROBE);
  console.log(name, JSON.stringify(info));
  const h = Math.min(info.docH, 9000);
  await send('Emulation.setDeviceMetricsOverride', { width, height: h, deviceScaleFactor: 1, mobile: width < 700 });
  await sleep(500);
  const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  writeFileSync(join(outDir, name + '.png'), Buffer.from(shot.result.data, 'base64'));
}
ws.close(); proc.kill();
process.exit(0);
"}

