/** Sheet metadata + links for a project (home sheet and case-study page). */
import type { CollectionEntry } from 'astro:content';
import { t, type Lang } from '../i18n/ui';

interface Props {
  project: CollectionEntry<'projects'>;
  full?: boolean;
  lang?: Lang;
}
const { project, full = false, lang = 'en' } = Astro.props;
const tr = t(lang);
const d = project.data;
const team = d.team === 1 ? `${tr('meta.solo')}, ${d.year}` : `${tr('meta.teamOf')} ${d.team}, ${d.year}`;
---

<dl class="meta">
